/** @brief Test that adc_emul_const_value_set() rejects a channel one past the
 *         emulator's configured channel count.
 */
ZTEST_USER(adc_emul, test_adc_emul_const_value_set_invalid_channel)
{
	int ret;
	const struct device *adc_dev = get_adc_device();

	ret = adc_emul_const_value_set(adc_dev, ADC_INVALID_CHANNEL_ID, 1500);
	zassert_equal(ret, -EINVAL,
		      "adc_emul_const_value_set() should reject out-of-range channel %d, got %d",
		      ADC_INVALID_CHANNEL_ID, ret);
}
